const runStart = $now.setZone('Asia/Seoul');

return [{
  json: {
    runStart: runStart.toFormat('yyyy-LL-dd HH:mm:ss'),
    windowDays: Math.trunc(56),
    linkRadiusM: Math.trunc(800),
  },
}];

const context = $('설정').first().json;
const failed = $input.all().some((item) => item.json.error != null);

return [{
  json: {
    ...context,
    ok: !failed,
    stage: 'UPSERT',
    reason: failed ? 'DB_UPSERT_FAILED' : null,
  },
}];

const context = $('혼잡 집계표 적재 판정').first().json;
const failed = $input.all().some((item) => item.json.error != null);

return [{
  json: {
    ...context,
    ok: !failed,
    stage: 'CLEANUP',
    reason: failed ? 'DB_CLEANUP_FAILED' : null,
  },
}];

const context = $input.first().json;
const stage = String(context.stage || 'UNKNOWN');
const reason = String(context.reason || 'UNKNOWN');

throw new Error(stage + ': ' + reason);

const context = $input.first().json;

return [{
  json: {
    ok: true,
    runStart: context.runStart,
    windowDays: context.windowDays,
    linkRadiusM: context.linkRadiusM,
  },
}];
